1	"use server";
2	
3	/**
4	 * Changes a member's role, keeping at least one owner.
5	 *
6	 * Owner D. Two guards that are easy to get wrong: nobody may grant a role above
7	 * their own (`hasRoleAtLeast`), and the last owner may not be demoted —
8	 * `MemberService.assertLastOwnerRetained` owns that second rule because it
9	 * needs to count owners.
10	 *
11	 * Must call (do not reimplement): updateMemberRoleSchema, can, hasRoleAtLeast,
12	 * getActor, toActionResult
13	 */
14	
15	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
16	import { withAction } from "@/actions/_lib/with-action";
17	import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
18	import { can } from "@/lib/permissions";
19	import {
20	  updateMemberRoleSchema,
21	  type UpdateMemberRoleInput,
22	} from "@/schemas/member";
23	import {
24	  assertLastOwnerRetained,
25	  updateMemberRole,
26	} from "@/server/services/member-service";
27	import type { ActionResult } from "@/types/api";
28	import { hasRoleAtLeast, type Member } from "@/types/member";
29	
30	const run = withAction<typeof updateMemberRoleSchema, Member>(
31	  updateMemberRoleSchema,
32	  async (raw, actor) => {
33	    const input = raw as UpdateMemberRoleInput;
34	
35	    const allowed = can(actor, "member:update_role", {
36	      kind: "member",
37	      orgId: input.orgId,
38	      memberId: input.memberId,
39	      targetUserId: actor.userId,
40	      targetRole: input.role,
41	    });
42	    if (!allowed) {
43	      throw new ForbiddenActionError("member:update_role");
44	    }
45	
46	    // Privilege escalation guard: an admin cannot mint an owner.
47	    if (!hasRoleAtLeast(actor.role, input.role)) {
48	      throw new ForbiddenActionError("member:update_role");
49	    }
50	
51	    await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
52	
53	    const member = await updateMemberRole(actor, input);
54	    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
55	    return member;
56	  },
57	  { revalidate: ["members"], cacheProfile: "minutes" },
58	);
59	
60	export async function updateMemberRoleAction(raw: unknown): Promise<ActionResult<Member>> {
61	  return run(raw);
62	}
